SET search_path TO axsuck, public;

-- Vehicle pools become templates: a name, the event type they belong to,
-- the game modes they are for (empty = every mode), Ban / Pick rules and
-- an order. Events pick the most specific template for their type and mode
-- unless an admin sets one (tournaments.vehicle_template).
ALTER TABLE vehicle_pools
  ADD COLUMN IF NOT EXISTS name TEXT,
  ADD COLUMN IF NOT EXISTS event_type TEXT,
  ADD COLUMN IF NOT EXISTS game_modes TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS rules JSONB NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS sort_order INTEGER NOT NULL DEFAULT 100,
  ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

-- The four pools the web app used to bundle. A pool already edited on the
-- site keeps its vehicles; only its name, type, modes and order are set.
INSERT INTO vehicle_pools (id, name, event_type, game_modes, rules, sort_order, vehicles, updated_at)
