UPDATE vehicle_pools SET name = id WHERE name IS NULL;
UPDATE vehicle_pools SET event_type = 'prop' WHERE event_type IS NULL;
ALTER TABLE vehicle_pools ALTER COLUMN name SET NOT NULL, ALTER COLUMN event_type SET NOT NULL;

-- An admin's choice of template for one event; NULL = pick automatically.
ALTER TABLE tournaments ADD COLUMN IF NOT EXISTS vehicle_template TEXT
  REFERENCES vehicle_pools(id) ON DELETE SET NULL ON UPDATE CASCADE;
